from engine import span
def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='En los siglos XIV y XV la literatura castellana se abre a la experiencia personal, a la sátira y a la reflexión sobre el tiempo. Este capítulo estudia dos obras muy distintas: el Libro de buen amor de Juan Ruiz, una colección heterogénea de materiales en torno a una autobiografía fingida, y las Coplas de Jorge Manrique, una elegía de cuarenta estrofas sobre la muerte de su padre.',
        quotes=[Q('es_lba','Está considerada una de las cumbres literarias españolas de cualquier tiempo'), Q('en_lba','considered to be one of the masterpieces of Spanish poetry')]))
    P.append(dict(text='El Libro de buen amor se atribuye a Juan Ruiz, arcipreste de Hita. Sus manuscritos no dan título: el nombre actual lo propuso Ramón Menéndez Pidal en 1898 a partir de pasajes del propio libro, sobre todo de la cuaderna 933b, cuyo primer hemistiquio dice «Buen amor dixe al libro». Se conservan tres manuscritos, ninguno completo, y la fecha de redacción varía según el códice: en uno el autor afirma haber terminado la obra en 1330 y en otro en 1343, de modo que la segunda versión sería una revisión de la primera con composiciones añadidas.',
        quotes=[Q('es_lba','El título con que hoy se conoce la obra fue propuesto por Menéndez Pidal en 1898','«\'Buen Amor\' dixe al libro»'), Q('en_lba','As for the date of writing, it varies according to the manuscript','added new compositions.')]))
    P.append(dict(text='La obra es una composición extensa, de más de 1700 estrofas de carácter variado, cuyo hilo conductor es una autobiografía ficticia del arcipreste. En ella el autor, representado en un episodio por don Melón de la Huerta, cuenta sus amores con mujeres de condición muy distinta —una monja, una mora, una panadera, varias serranas— ayudado por la alcahueta Urraca, llamada Trotaconventos, precedente claro de La Celestina. A través de sus amantes aparecen representadas todas las capas de la sociedad bajomedieval española.',
        quotes=[Q('es_lba','Es una composición extensa, formada por más de 1700 estrofas de carácter variado'), Q('en_lba','a character that constitutes the clearest precedent for La Celestina')]))
    P.append(dict(text='La variedad es la señal de identidad del libro: de contenido, con ejemplos, narraciones amorosas, serranillas, fábulas y composiciones líricas; de métrica, pues además de la cuaderna vía emplea estrofas de dieciséis versos y estrofas zejelescas, y de tono, que oscila entre lo serio y lo festivo, lo religioso y lo profano. Gran parte de los materiales narrativos parodia las comedias elegíacas latinas de ámbito escolar, como el Pamphilus, que sirve de base al episodio de don Melón y doña Endrina, y también se parodia la liturgia de las horas canónicas en el combate de don Carnal con doña Cuaresma.',
        quotes=[Q('es_lba','El libro se caracteriza por su variedad de:','Tono (serio, festivo, religioso, profano, etc.)'), Q('en_lba','Pamphilus is also cited in the Book of Good Love as the basis for the episode of Don Melón and Doña Endrina.')]))
    P.append(dict(text='El libro pertenece al mester de clerecía, pero lo renueva. La crítica actual considera que desciende de la literatura latina medieval clerical, aunque se hayan propuesto fuentes árabes, y la sátira social gana un lugar propio: Juan Ruiz critica el poder igualador del dinero, que permite quebrar las barreras entre estamentos. Este rasgo revela la tensión de una sociedad en la que el desarrollo de la burguesía disuelve poco a poco el orden de los tres estamentos medievales.',
        quotes=[Q('es_lba','Aunque se han propuesto fuentes árabes, la crítica actual se decanta por considerar que El libro de buen amor desciende de la literatura latina medieval clerical.'), Q('es_mester','la sátiras contra el poder igualador del dinero')]))
    P.append(dict(text='Un siglo más tarde, Jorge Manrique escribe las Coplas por la muerte de su padre, elegía por la muerte del maestre de Santiago Rodrigo Manrique, fallecido el 11 de noviembre de 1476. Pertenece al género medieval del planto y es una reflexión sobre la vida, la fama, la fortuna y la muerte con resignación cristiana, inspirada en precedentes clásicos y medievales y en el Eclesiastés. Manrique, nacido hacia 1440, pertenecía a una familia noble de gran importancia literaria —era sobrino de Gómez Manrique y sobrino nieto del marqués de Santillana— y murió en 1479 durante un asalto al castillo de Garcimuñoz.',
        quotes=[Q('es_coplas','son una elegía escrita por Jorge Manrique en la muerte de su padre, el maestre de Santiago Rodrigo Manrique'), Q('en_manrique','Jorge Manrique (c. 1440 – 24 April 1479) was a major Castilian poet')]))
    P.append(dict(text='La forma métrica es la que hoy se llama copla manriqueña o copla de pie quebrado: cuarenta estrofas, cada una de ellas una sextilla doble de doce versos, con octosílabos en primero, segundo, cuarto y quinto lugar y tetrasílabos en el tercero y el sexto, con rima abc abc def def. Manrique no inventó este esquema, que ya habían usado Juan de Mena y su tío Gómez Manrique, pero lo elevó a la máxima categoría. La alternancia de versos largos y breves daba a la estrofa flexibilidad para sonar grave o ligera.',
        quotes=[Q('es_coplas','a lo largo de cuarenta estrofas llamadas coplas de pie quebrado o sextillas manriqueñas','tetrasílabos tercero y sexto'), Q('en_manrique','The poem has forty stanzas, each composed of twelve eight- and four-syllable lines')]))
    P.append(dict(text='La estructura del poema sigue un movimiento de lo general a lo particular. La primera parte (coplas I-XIV) reflexiona sobre la vida y la muerte y se parece más a un sermón filosófico que a una elegía. La segunda (XV-XXIV) concreta esas ideas en ejemplos de muertes recientes mediante la interrogación retórica del ubi sunt. La tercera (XXV-XL) es la elegía propiamente dicha: retrata a Rodrigo Manrique como caballero que cumplió los deberes de la nobleza y termina con un diálogo dramático entre el maestre y la Muerte. El poema distingue además tres tipos de vida: la terrenal, la de la fama y la eterna.',
        quotes=[Q('es_coplas','3.ª parte (coplas XXV-XL) (sobre su padre)','la elegía propiamente dicha'), Q('en_manrique','He makes a reference to three lives:')]))
    P.append(dict(text='Los temas de las Coplas son tópicos de larga tradición: el paso inexorable del tiempo (tempus fugit), la vida como camino (homo viator) y como río que desemboca en la muerte, la muerte que iguala a ricos y pobres y la vanidad de las cosas mundanas. Manrique los trata con un lenguaje preciso y sin adorno, que se centra en lo que se dice más que en cómo se dice. Lope de Vega consideró la obra digna de ser impresa con letras de oro.',
        quotes=[Q('es_coplas','El paso inexorable del tiempo (tópico del tempus fugit).','La vanidad de las cosas mundanas'), Q('en_manrique','The language Manrique uses is precise, exact, without decoration or difficult metaphors.')]))
    P.append(dict(role='definition', text='Ubi sunt: tópico medieval, tomado de la expresión latina «¿dónde están?», que consiste en preguntar retóricamente por personas y bienes desaparecidos para mostrar que todas las cosas de este mundo son perecederas. Las Coplas de Manrique lo emplean con frecuencia en su segunda parte.',
        quotes=[Q('es_coplas','Empleo de la interrogación retórica del ubi sunt','como la propia vida terrenal'), Q('en_manrique','These examples are introduced by the rhetorical questions called ubi sunt (Where are they?)')]))
    P.append(dict(role='consejo', text='Cuando analice una copla manriqueña, escriba en una columna el número de sílabas de cada verso y compruebe el patrón 8-8-4, 8-8-4 en cada sextilla. Si un verso corto parece de cinco sílabas, mire si el verso anterior termina en palabra aguda: la ley de compensación explica la diferencia.',
        quotes=[Q('es_coplas','los tetrasílabos pueden ser en apariencia pentasílabos algunas veces'), Q('en_manrique','Every third line is a quebrado (half line).')]))
    P.append(dict(role='self_check', text='¿Qué rasgos del Libro de buen amor lo apartan de la clerecía del siglo XIII? ¿Por qué se considera a Trotaconventos un precedente de La Celestina? ¿Cómo se organizan las tres partes de las Coplas y qué función cumple el ubi sunt?',
        quotes=[Q('es_lba','Trotaconventos, personaje que constituye el precedente más claro de La Celestina'), Q('en_manrique','The last part of the poem is devoted to his father')]))
    return P

def _legacy_numeric_problems(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    return [dict(role='worked', problem_type='NUMERICAL',
        prompt='Las Coplas de Manrique tienen cuarenta estrofas de doce versos. Según una división habitual, la tercera parte, dedicada al padre del poeta, abarca las coplas XXV a XL. Calcule cuántas estrofas y cuántos versos tiene esa parte y qué porcentaje del poema representa.',
        expected='40', quotes=[Q('es_coplas','3.ª parte (coplas XXV-XL) (sobre su padre)'), Q('en_manrique','The poem has forty stanzas, each composed of twelve eight- and four-syllable lines')],
        method='Contar estrofas de un intervalo cerrado y expresar la razón como porcentaje',
        solution=dict(given=[dict(symbol='c_i',value=25,unit='dimensionless',meaning='primera copla de la tercera parte'),dict(symbol='c_f',value=40,unit='dimensionless',meaning='última copla del poema'),dict(symbol='v',value=12,unit='dimensionless',meaning='versos por copla')],
          unknown='El número de coplas, el de versos de la tercera parte y su porcentaje sobre el poema.',
          model=[dict(name='Estrofas de un intervalo cerrado',latex='n = c_f - c_i + 1',symbolic='c_f - c_i + 1'),dict(name='Versos',latex='V = n\\,v',symbolic='n*v'),dict(name='Porcentaje',latex='p = 100\\,\\frac{n}{c_f}',symbolic='100*n/c_f')],
          assumptions=['Las coplas se numeran de la I a la XL sin saltos y todas tienen doce versos.'],
          development=['Como en el cantar del Cid, el intervalo es cerrado: se incluyen ambos extremos.'],
          steps=[dict(text='Estrofas de la tercera parte',equation='n = 40 - 25 + 1',expression='40-25+1',expected=16,unit='dimensionless'),
                 dict(text='Versos de la tercera parte',equation='V = 16 \\cdot 12',expression='16*12',expected=192,unit='dimensionless'),
                 dict(text='Porcentaje del poema',equation='p = 100 \\cdot 16/40',expression='100*16/40',expected=40,unit='dimensionless')],
          result='La tercera parte tiene 16 coplas y 192 versos, el 40 % del poema.',
          interpretation='La elegía propiamente dicha ocupa menos de la mitad del poema: casi dos tercios de las coplas preparan la alabanza del padre con reflexiones generales y ejemplos.',
          limitations=['Otras descripciones del poema dividen las coplas de manera distinta, por ejemplo en secciones de 1-24, 25-32, 33-39 y 40.'],
          mistakes=['Restar 40 - 25 sin sumar uno e inferir 15 coplas.']))]


